import assert from 'node:assert/strict';
export const additions={"/clinic-gone-quiet": "<section data-content-review=\"2026-10-09\"><h2>First decide what you need help with</h2><p><strong>A health concern needs a clinical route.</strong> Do not wait for a customer-service reply if you need urgent medical help. Use <a href=\"/help\">the urgent-help routes for your part of the UK</a>; for a life-threatening emergency, call 999. SHIFT check-ins are not monitored clinical messages.</p><p><strong>A missing order needs an order answer.</strong> Find the order reference and ask whether assessment, prescribing, dispensing or delivery is holding it up. Payment taken, a prescription approved and a parcel dispatched are different stages. Ask which stage your order has reached and when you should expect the next update.</p><p><strong>Running out needs individual advice.</strong> Tell your prescriber or pharmacist what you take, when you last took it and how much you have left. The <a href=\"https://www.nhs.uk/nhs-services/prescriptions/emergency-prescriptions/\">NHS explains how to seek help when prescribed medicine runs out</a>. This does not guarantee emergency supply of a particular medicine or transfer of private treatment to the NHS.</p></section><section><h2>Make the next contact easier to answer</h2><p>Use the provider's secure account or published contact route. Keep the date and a copy of your message. Avoid putting health details into a public review or social-media comment.</p><blockquote><p>“My reference is [reference]. I contacted you on [date] about [problem]. Please confirm who is handling this, what information you still need and when I should expect a reply. If you cannot continue my care, please explain how I can obtain the relevant treatment records and who I should contact next.”</p></blockquote><p>This is a prompt to adapt, not a message SHIFT sends for you. If the response is overdue, follow the provider's complaints process for the service issue while seeking clinical advice separately where needed. Keep receipts and any cancellation confirmation together.</p></section><section><h2>What you can do today without a new prescription</h2><p>Write down the question you need answered and gather the records you already hold. Choose one manageable food or movement routine to keep going. You do not need to solve everything in one sitting. SHIFT can help organise everyday support; it cannot recover another clinic's records, arrange a prescription or guarantee a reply from them.</p></section>", "/provider-switch": "<section data-content-review=\"2026-10-09\"><h2>Compare the cost you will actually pay</h2><p>Use the same medicine, strength, pack quantity and supply duration when comparing quotes. A first-order discount is not a repeat price. If the next dose has a different price, record that separately rather than assuming the starting price continues.</p><ul><li><strong>First supply:</strong> medicine plus any compulsory assessment, membership and delivery charges, after a discount you qualify for.</li><li><strong>Repeat supply:</strong> the undiscounted total, what it includes and how often you will be charged.</li><li><strong>Commitment:</strong> minimum term, renewal date, notice period and what happens to charges if treatment is declined, paused or changed.</li><li><strong>Support:</strong> who answers clinical questions, how to reach them and what continues if medicine purchases stop.</li></ul><p>A four-week billing cycle is not a calendar month: thirteen 28-day periods cover 364 days. For a longer commitment, ask for the total payable over the actual contract and the number of supplies it includes. Do not multiply an introductory price and call it the annual cost.</p></section><section><h2>Check the handover before relying on it</h2><ol><li><strong>Identify the service.</strong> Ask for the dispensing pharmacy and prescribing provider, not only the brand name. For pharmacies in Great Britain, the <a href=\"https://inspections.pharmacyregulation.org/home/index\">GPhC inspection service</a> shows published findings against pharmacy standards; it also links to the register. An inspection report is not a guarantee that your treatment will be approved.</li><li><strong>Ask what evidence is needed.</strong> Check whether your existing records are sufficient, how to submit them securely and whether a further assessment is required.</li><li><strong>Get an individual plan.</strong> Ask the new prescriber to confirm whether they can take over, what treatment they recommend and how any gap should be handled. Do not infer dosing or restart instructions from a price page.</li><li><strong>Separate clinical and account decisions.</strong> Check the old provider's renewal and cancellation rules and the new service's assessment and fulfilment times. Keep written confirmations so you can spot overlapping charges. A dispatch estimate is not clinical approval.</li></ol><p>If the new provider declines treatment, ask what follow-up they recommend. Organising another assessment does not itself resolve a treatment gap.</p></section><section><h2>Your five-minute handover note</h2><p>In a private note, record: why you want to move; medicine and dose if applicable; last dose date; remaining supply; concerns or side effects; and the one question you want the clinician to answer first. Attach records only through the provider's secure route. Your own note helps the conversation; it does not replace their assessment or your clinical record.</p><p><strong>Next step:</strong> gather the missing information before choosing on headline price. If the problem is an unanswered message, use the <a href=\"/clinic-gone-quiet\">clinic-not-responding guide</a>.</p></section>"};
// Remove only the finite registered addition; preserve every surrounding body byte.
export function preserveContinuityUpgrade(path,input,{required=false}={}){
 const addition=additions[path];if(!addition)return input;
 let html=input.toString('utf8');assert(Buffer.from(html).equals(input),'UTF-8 required');
 const n=html.split(addition).length-1;assert(n<=1,path+' duplicate approved content');
 if(required)assert.equal(n,1,path+' missing exact registered content');
 if(n)html=html.replace(addition,'');
 assert(!html.includes('data-content-review="2026-10-09"'),path+' unrecognised content amendment');
 // The two pages keep their original publication dates; normalise only known modified dates.
 const old=path==='/clinic-gone-quiet'?'2026-10-07':'2026-09-17';
 html=html.replaceAll('"dateModified":"2026-10-09"','"dateModified":"'+old+'"');
 return Buffer.from(html);
}
